/* @lc app=leetcode id=3820 lang=kotlin */ class Solution { fun bfs(g: Map<Int, List<Int>>, n: Int, s: Int): IntArray = IntArray(n) { -1 }.also { it[s] = 0 }.also { d -> generateSequence(listOf(s)) { f -> f.flatMap { u -> g[u].orEmpty().filter { d[it] == -1 }.distinct().onEach { v -> d[v] = d[u] + 1 } }.takeIf { it.isNotEmpty() } }.count() } fun specialNodes(n: Int, edges: Array<IntArray>, x: Int, y: Int, z: Int): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> bfs(g, n, x).let { dx -> bfs(g, n, y).let { dy -> bfs(g, n, z).let { dz -> (0 until n).count { u -> listOf(dx[u], dy[u], dz[u]).sorted().let { (a, b, c) -> a.toLong() * a + b.toLong() * b == c.toLong() * c } } } } } } }